-- ============================================================================
-- Veille BF — Schéma Postgres (Supabase), porté depuis SQLite.
-- Appliqué au projet Supabase ScrapperBF (ref xuuxlgfarskzrttugrkh) le 2026-11-28
-- via migration "schema_initial_veillebf".
--
-- Choix de portage :
--   * INTEGER -> BIGINT (montants FCFA), REAL -> DOUBLE PRECISION
--   * Booléens stockés 0/1 -> SMALLINT (conserve la compat des requêtes "= 1")
--   * AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   * TIMESTAMP DEFAULT CURRENT_TIMESTAMP -> TIMESTAMPTZ DEFAULT now()
--   * cree_le/maj_le stockés en TEXT côté SQLite (support_*, user_details) -> TEXT
-- Le backend se connecte en direct (rôle postgres) : RLS activé ne le bloque pas.
-- ============================================================================

CREATE TABLE IF NOT EXISTS plans (
  id TEXT PRIMARY KEY, nom TEXT NOT NULL, sous_titre TEXT,
  prix_mensuel_fcfa BIGINT NOT NULL DEFAULT 0, prix_annuel_fcfa BIGINT NOT NULL DEFAULT 0,
  features_json TEXT NOT NULL DEFAULT '{}', ordre INTEGER NOT NULL DEFAULT 0, actif SMALLINT NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, nom TEXT, organisation TEXT, telephone TEXT,
  plan_id TEXT NOT NULL DEFAULT 'gratuit' REFERENCES plans(id), role TEXT NOT NULL DEFAULT 'user',
  email_verifie SMALLINT NOT NULL DEFAULT 0, cree_le TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS subscriptions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  plan_id TEXT NOT NULL REFERENCES plans(id), statut TEXT NOT NULL DEFAULT 'active',
  cycle TEXT NOT NULL DEFAULT 'mensuel', debut TIMESTAMPTZ DEFAULT now(), fin TIMESTAMPTZ, cree_le TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS payments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  subscription_id BIGINT REFERENCES subscriptions(id) ON DELETE SET NULL,
  plan_id TEXT, cycle TEXT, montant_fcfa BIGINT NOT NULL DEFAULT 0, provider TEXT, operateur TEXT, telephone TEXT,
  reference_interne TEXT UNIQUE, reference_externe TEXT, statut TEXT NOT NULL DEFAULT 'pending', payload_json TEXT,
  cree_le TIMESTAMPTZ DEFAULT now(), maj_le TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS usage_counters (
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, periode TEXT NOT NULL,
  compteur_recherches INTEGER NOT NULL DEFAULT 0, compteur_fiches INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, periode)
);
CREATE TABLE IF NOT EXISTS api_keys (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, cle_hash TEXT NOT NULL UNIQUE,
  prefixe TEXT NOT NULL, label TEXT, actif SMALLINT NOT NULL DEFAULT 1,
  cree_le TIMESTAMPTZ DEFAULT now(), derniere_utilisation TIMESTAMPTZ
);
CREATE TABLE IF NOT EXISTS team_members (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  owner_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  member_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL DEFAULT 'membre', cree_le TIMESTAMPTZ DEFAULT now(),
  UNIQUE(owner_user_id, member_user_id)
);
CREATE TABLE IF NOT EXISTS profils_candidature (
  user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  secteurs TEXT, region TEXT, budget_min BIGINT, budget_max BIGINT, agrements TEXT, anciennete_annees INTEGER,
  en_groupement SMALLINT NOT NULL DEFAULT 0, marches_soumis INTEGER NOT NULL DEFAULT 0,
  marches_gagnes INTEGER NOT NULL DEFAULT 0, maj_le TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS groupement_profils (
  user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  secteurs TEXT, agrements TEXT, contact TEXT, message TEXT, actif SMALLINT NOT NULL DEFAULT 1, cree_le TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS radar_concurrents (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, entreprise_nom TEXT NOT NULL,
  cree_le TIMESTAMPTZ DEFAULT now(), UNIQUE(user_id, entreprise_nom)
);
CREATE TABLE IF NOT EXISTS coffre_documents (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, nom TEXT NOT NULL, type TEXT, taille BIGINT, chemin TEXT NOT NULL,
  cree_le TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS alertes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT REFERENCES users(id) ON DELETE CASCADE, secteur TEXT, type_marche TEXT, region TEXT,
  canal TEXT NOT NULL DEFAULT 'email', cible TEXT, actif SMALLINT NOT NULL DEFAULT 1, cree_le TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS user_details (
  user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  nom_entreprise TEXT, secteur_principal TEXT, secteurs_secondaires TEXT, annee_creation INTEGER, ville TEXT,
  pays TEXT DEFAULT 'Burkina Faso', ifu TEXT, rccm TEXT, forme_juridique TEXT, fonction_poste TEXT, maj_le TEXT
);
CREATE TABLE IF NOT EXISTS support_tickets (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, user_email TEXT, user_nom TEXT, sujet TEXT NOT NULL,
  categorie TEXT DEFAULT 'Général', statut TEXT DEFAULT 'ouvert', cree_le TEXT NOT NULL, maj_le TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS support_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ticket_id BIGINT NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,
  sender_id BIGINT NOT NULL, sender_nom TEXT, sender_role TEXT DEFAULT 'user', message TEXT NOT NULL, cree_le TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS annonces_avis (
  id TEXT PRIMARY KEY, source_file TEXT, numero_bulletin TEXT, date_parution TEXT, pages TEXT,
  categorie_marche TEXT, type_procedure TEXT, reference_dossier TEXT, autorite_contractante TEXT, ministere_tutelle TEXT,
  objet_marche TEXT, allotissement_type TEXT, nombre_lots INTEGER, budget_previsionnel_fcfa BIGINT,
  garantie_soumission_fcfa BIGINT, cout_acquisition_dossier_fcfa BIGINT, source_financement TEXT, exercice_budgetaire TEXT,
  date_limite_depot TEXT, heure_limite_depot TEXT, delai_execution_jours INTEGER, delai_validite_offres_jours INTEGER,
  lieu_depot_offres TEXT, date_heure_ouverture_plis TEXT, lieu_ouverture_plis TEXT, marche_reserve TEXT,
  qualifications_ou_agrement TEXT, contacts_renseignements TEXT, signataire_nom_fonction TEXT, remarque TEXT, json_brut TEXT,
  date_extraction TIMESTAMPTZ DEFAULT now(), secteur_activite TEXT
);
CREATE TABLE IF NOT EXISTS detail_lots (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  annonce_id TEXT REFERENCES annonces_avis(id) ON DELETE CASCADE,
  numero_lot TEXT, titre TEXT, description TEXT, montant_fcfa BIGINT, caution_fcfa BIGINT
);
CREATE TABLE IF NOT EXISTS resultats_marches (
  id TEXT PRIMARY KEY, bulletin TEXT, date_parution TEXT, pages TEXT, autorite_contractante TEXT,
  reference_dossier TEXT, reference_normalisee TEXT, annonce_avis_id TEXT REFERENCES annonces_avis(id) ON DELETE SET NULL,
  objet TEXT, secteur_activite TEXT, financement TEXT, date_depouillement TEXT, date_deliberation TEXT,
  nombre_lots INTEGER DEFAULT 1, budget_previsionnel_min_fcfa BIGINT, budget_previsionnel_max_fcfa BIGINT,
  source_file TEXT, json_brut TEXT, date_extraction TIMESTAMPTZ DEFAULT now(), methode_selection TEXT,
  score_technique_min_requis DOUBLE PRECISION, decision_arcop_ref TEXT, est_rectificatif SMALLINT DEFAULT 0,
  remarques_extracteur TEXT, statut_coherence TEXT DEFAULT 'CONFORME', audit_statut TEXT DEFAULT 'NON_AUDITE',
  audit_details TEXT, annee INTEGER, date_iso TEXT, reference_avis_publication TEXT
);
CREATE TABLE IF NOT EXISTS resultats_lots (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  resultat_id TEXT REFERENCES resultats_marches(id) ON DELETE CASCADE,
  numero_lot INTEGER, intitule_lot TEXT, nombre_plis_recus INTEGER, budget_lot_min_fcfa BIGINT, budget_lot_max_fcfa BIGINT,
  moyenne_offres_fcfa BIGINT, borne_inf_basse_fcfa BIGINT, seuil_tolerance_5pct_fcfa BIGINT, borne_sup_elevee_fcfa BIGINT,
  attributaire_nom TEXT, montant_attribue_min_fcfa BIGINT, montant_attribue_max_fcfa BIGINT, delai_execution TEXT,
  est_infructueux SMALLINT DEFAULT 0, motif_infructueux TEXT, remarques_extracteur TEXT, statut_coherence TEXT DEFAULT 'CONFORME',
  audit_statut TEXT DEFAULT 'NON_AUDITE', audit_details TEXT, contacts_entreprises TEXT, remarques_autorite TEXT,
  moyenne_offres_p_fcfa BIGINT, moyenne_ponderee_m_fcfa BIGINT
);
CREATE TABLE IF NOT EXISTS resultats_soumissionnaires (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  resultat_id TEXT REFERENCES resultats_marches(id) ON DELETE CASCADE,
  lot_id BIGINT REFERENCES resultats_lots(id) ON DELETE CASCADE,
  nom_soumissionnaire TEXT, nom_canonique TEXT,
  montant_lu_htva_min BIGINT, montant_lu_htva_max BIGINT, montant_lu_ttc_min BIGINT, montant_lu_ttc_max BIGINT,
  montant_corrige_htva_min BIGINT, montant_corrige_htva_max BIGINT, montant_corrige_ttc_min BIGINT, montant_corrige_ttc_max BIGINT,
  conformite TEXT, classement TEXT, rang_numerique INTEGER, est_attributaire SMALLINT DEFAULT 0, observations_motifs TEXT,
  ifu TEXT, rccm TEXT, telephone TEXT, email TEXT, adresse_bp TEXT, score_technique DOUBLE PRECISION,
  est_groupement SMALLINT DEFAULT 0, membres_groupement TEXT, categorie_rejet TEXT, criteres_evaluation TEXT
);
CREATE TABLE IF NOT EXISTS entreprises (
  nom_canonique TEXT PRIMARY KEY, ifu TEXT, rccm TEXT, telephone TEXT, email TEXT, adresse_bp TEXT, ville TEXT,
  secteurs_json TEXT, est_groupement SMALLINT DEFAULT 0, nb_soumissions INTEGER DEFAULT 0, nb_gagnes INTEGER DEFAULT 0,
  nb_conformes INTEGER DEFAULT 0, taux_reussite INTEGER DEFAULT 0, montant_total_gagne_fcfa BIGINT DEFAULT 0
);
CREATE TABLE IF NOT EXISTS communiques (
  id TEXT PRIMARY KEY, numero_bulletin TEXT, bulletin_num INTEGER, numero_ordre INTEGER, date_parution TEXT, page INTEGER,
  methode_detection TEXT, bbox_json TEXT, type_brut TEXT, texte_integral TEXT NOT NULL, source_file TEXT,
  type_communique TEXT, autorite_emetteur TEXT, reference_marche_lie TEXT, reference_normalisee TEXT, bulletin_origine TEXT,
  objet_marche TEXT, nouvelle_date_limite TEXT, nouvelle_heure_limite TEXT, ancienne_date TEXT, motif_action TEXT,
  signataire TEXT, variables_json TEXT, statut_extraction TEXT DEFAULT 'BRUT', date_extraction TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS suivis (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, avis_id TEXT NOT NULL,
  statut TEXT NOT NULL DEFAULT 'suivi', note TEXT, scoring_snapshot_json TEXT, cree_le TIMESTAMPTZ DEFAULT now(),
  UNIQUE(user_id, avis_id)
);
CREATE TABLE IF NOT EXISTS dossiers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, avis_id TEXT NOT NULL,
  statut TEXT NOT NULL DEFAULT 'a_etudier', cree_le TIMESTAMPTZ DEFAULT now(), maj_le TIMESTAMPTZ DEFAULT now(),
  UNIQUE(user_id, avis_id)
);
CREATE TABLE IF NOT EXISTS dossier_pieces (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  dossier_id BIGINT NOT NULL REFERENCES dossiers(id) ON DELETE CASCADE,
  libelle TEXT NOT NULL, coche INTEGER NOT NULL DEFAULT 0, ordre INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS notifications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type TEXT NOT NULL, avis_id TEXT, resultat_id TEXT, titre TEXT, message TEXT, payload_json TEXT,
  lu SMALLINT NOT NULL DEFAULT 0, cree_le TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_subs_user ON subscriptions(user_id);
CREATE INDEX IF NOT EXISTS idx_payments_user ON payments(user_id);
CREATE INDEX IF NOT EXISTS idx_suivis_user ON suivis(user_id);
CREATE INDEX IF NOT EXISTS idx_notif_user ON notifications(user_id, lu);
CREATE UNIQUE INDEX IF NOT EXISTS idx_notif_unique ON notifications(user_id, type, resultat_id);
CREATE INDEX IF NOT EXISTS idx_radar_user ON radar_concurrents(user_id);
CREATE INDEX IF NOT EXISTS idx_dossiers_user ON dossiers(user_id);
CREATE INDEX IF NOT EXISTS idx_dossier_pieces ON dossier_pieces(dossier_id);
CREATE INDEX IF NOT EXISTS idx_detail_lots_annonce ON detail_lots(annonce_id);
CREATE INDEX IF NOT EXISTS idx_rm_annonce ON resultats_marches(annonce_avis_id);
CREATE INDEX IF NOT EXISTS idx_rl_resultat ON resultats_lots(resultat_id);
CREATE INDEX IF NOT EXISTS idx_rs_resultat ON resultats_soumissionnaires(resultat_id);
CREATE INDEX IF NOT EXISTS idx_rs_lot ON resultats_soumissionnaires(lot_id);
CREATE INDEX IF NOT EXISTS idx_rs_canon ON resultats_soumissionnaires(nom_canonique);
CREATE INDEX IF NOT EXISTS idx_aa_secteur ON annonces_avis(secteur_activite);
